    const std::size_t pixelBytes=std::size_t(width)*height*4u;std::vector<std::byte> bytes(54u+pixelBytes);bytes[0]=std::byte{'B'};bytes[1]=std::byte{'M'};Put32(bytes,2,std::uint32_t(bytes.size()));Put32(bytes,10,54);Put32(bytes,14,40);Put32(bytes,18,width);Put32(bytes,22,height);bytes[26]=std::byte{1};bytes[28]=std::byte{32};Put32(bytes,34,std::uint32_t(pixelBytes));
