    bytes[offset]=bytes[offset+1]=std::byte{alpha};for(unsigned index=2;index<8;++index)bytes[offset+index]=std::byte{};const std::uint16_t color=Rgb565(255,roughness,0);bytes[offset+8]=bytes[offset+10]=std::byte(color&255u);bytes[offset+9]=bytes[offset+11]=std::byte(color>>8);for(unsigned index=12;index<16;++index)bytes[offset+index]=std::byte{};offset+=16;
