CardHalves MeasureHalves(const D3D12RendererTestAccess3D::LinearHdrCapture3D& hdr,const ObjectIdCapture3D& oid,const RenderObjectIdentity3D& identity){CardHalves result{};for(std::size_t index=0;index<oid.pixels.size();++index){const auto* resolved=oid.Resolve(oid.pixels[index]);if(!resolved||*resolved!=identity)continue;const float luma=.2126f*hdr.pixels[index].x+.7152f*hdr.pixels[index].y+.0722f*hdr.pixels[index].z;const unsigned x=unsigned(index%oid.width);if(x<oid.width/2){result.left+=luma;++result.leftCount;}else{result.right+=luma;++result.rightCount;}}if(result.leftCount)result.left/=float(result.leftCount);if(result.rightCount)result.right/=float(result.rightCount);return result;}
