NightObjectSample MeasureNightObject(const D3D12RendererTestAccess3D::LinearHdrCapture3D& capture,const ObjectIdCapture3D& oid,const RenderObjectIdentity3D& identity,float darkThreshold=.0003f){NightObjectSample result{};std::vector<float> lumas;Vec3 rgb{};for(std::size_t index=0;index<oid.pixels.size();++index)if(const auto* resolved=oid.Resolve(oid.pixels[index]);resolved&&*resolved==identity){const auto pixel=capture.pixels[index];const float luma=.2126f*pixel.x+.7152f*pixel.y+.0722f*pixel.z;lumas.push_back(luma);rgb=rgb+Vec3{pixel.x,pixel.y,pixel.z};result.darkFraction+=luma<=darkThreshold?1.f:0.f;}result.count=lumas.size();if(!result.count)return result;std::ranges::sort(lumas);result.p10=lumas[(result.count-1)/10];result.mean=std::accumulate(lumas.begin(),lumas.end(),0.f)/float(result.count);result.darkFraction/=float(result.count);rgb=rgb*(1.f/float(result.count));result.chroma=((std::max)({rgb.x,rgb.y,rgb.z})-(std::min)({rgb.x,rgb.y,rgb.z}))/(result.mean+.0001f);return result;}
